class Solution {
    long long cost(const vector<int>& nums) {
        priority_queue<int> heap;
        long long answer = 0;
        for (int x : nums) {
            heap.push(x);
            if (heap.top() > x) {
                answer += heap.top() - x;
                heap.pop();
                heap.push(x);
            }
        }
        return answer;
    }
public:
    int convertArray(vector<int>& nums) {
        long long first = cost(nums);
        vector<int> negated(nums);
        for (int& x : negated) x = -x;
        return (int)min(first, cost(negated));
    }
};
